// Restarts the lock delay of a resting piece, within the per-piece limit.
function restartLockDelay() {
  if (state.lockTicks > 0 && state.lockResets < MAX_LOCK_RESETS) {
    state.lockTicks = 0;
    state.lockResets++;
  }
}

